Start-Transcript -Path "C:\Scripts\last-update-log.txt" -Force -ErrorAction SilentlyContinue; Write-Host "`n[1/2] Checking Winget App Updates (including unknown versions)..." -ForegroundColor Cyan; $w = Resolve-Path "C:\Program Files\WindowsApps\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\winget.exe" | Select-Object -Last 1 -ExpandProperty Path; if ($w) { &$w upgrade --all --include-unknown --accept-package-agreements --accept-source-agreements --silent }; Write-Host "`n[2/2] Scanning & Installing Windows Updates (this takes 30-60 seconds)..." -ForegroundColor Cyan; Import-Module PSWindowsUpdate; Install-WindowsUpdate -MicrosoftUpdate -AcceptAll -IgnoreReboot; Write-Host "`n--- All Updates Complete! ---" -ForegroundColor Green; Stop-Transcript -ErrorAction SilentlyContinue; if (Get-WURebootStatus -Silent) { Write-Host "'nRESTART FOR UPDATES TO TAKE EFFECT!" -Foreground Color Yellow (New-Object -ComObject Wscript.Shell).Popup("Updates Installed. Please Restart Your Computer To Finish.", 0, "Restart Required", 0x40) | Out-Null
